var DiagonalTick = (tip, lineDir, size) => {
  const perp = new Vector3(-lineDir.z, 0, lineDir.x);
  const diag = new Vector3(lineDir.x + perp.x, 0, lineDir.z + perp.z).normalize().multiplyScalar(size / 2);
  return [
    tip.x + diag.x,
    tip.y,
    tip.z + diag.z,
    tip.x - diag.x,
    tip.y,
    tip.z - diag.z
  ];
};
var ArrowTick = (tip, lineDir, size) => {
  const perp = new Vector3(-lineDir.z, 0, lineDir.x);
  const wing1x = tip.x - lineDir.x * size + perp.x * size * 0.4;
  const wing1z = tip.z - lineDir.z * size + perp.z * size * 0.4;
  const wing2x = tip.x - lineDir.x * size - perp.x * size * 0.4;
  const wing2z = tip.z - lineDir.z * size - perp.z * size * 0.4;
  return [
    tip.x,
    tip.y,
    tip.z,
    wing1x,
    tip.y,
    wing1z,
    tip.x,
    tip.y,
    tip.z,
    wing2x,
    tip.y,
    wing2z,
    wing1x,
    tip.y,
    wing1z,
    wing2x,
    tip.y,
    wing2z
  ];
};
